from taf.sbts.oam.coam.admin.interfaces.admin_22r3 import SBTS22R3
from taf.sbts.oam.coam.admin.schemas.procedure.ccm_uplink_prach_22r4 import CCMUplinkPrach
from taf.sbts.oam.coam.admin.utils import raise_value_error
from taf.sbts.oam.coam.admin.exceptions import NoCellsAvailable, CellGroupDoesntExist


class SBTS22R4(SBTS22R3):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS22R4, self).__init__(api_client)

    def lock(self, dist_name=None, timeout=30, technology=None, detailed_output=False):
        """
        Lock given resource.

        :param Union[str, list] dist_name: dist_name of <BBMOD|RMOD|ASIRMOD|TTRX_ST|LANE|NRDU|NRCELL|NRCELLGRP|LNCEL distName>
                                            From SBTS22R4 it could be list of items. Should be None when technology is specified
        :param timeout: (optional) Time to wait for positive procedure result.
        :param str technology: one of <LTE, TETRA, NR, ALL> - should be None when dist_name is specified.
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return: dict with full api response or requestMessage key
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-lock.html
        """
        if not (dist_name or technology):
            raise ValueError("dist_name or technology must be specified")

        if all([dist_name, technology]):
            raise ValueError("Only one of dist_name or technology must be specified")

        if technology not in ("LTE", "TETRA", "NR", "ALL", None):
            raise_value_error(param="technology",
                              value=str(technology),
                              subpage="tutorial-lock.html")

        if dist_name and not isinstance(dist_name, list):
            dist_name = [dist_name]
        keys = ["distNames", "technology"]
        values = [dist_name, technology]
        parameters = {k: v for (k, v) in zip(keys, values) if v}

        response = self._api_client.execute_customer_procedure('lock', parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def unlock(self, dist_name=None, timeout=30, technology=None, detailed_output=False):
        """
        Unlock given resource.

        :param Union[str, list] dist_name: dist_name of <BBMOD|RMOD|ASIRMOD|TTRX_ST|LANE|NRDU|NRCELL|NRCELLGRP|LNCEL distName>
                                            From SBTS22R4 it could be list of items. Should be None when technology is specified
        :param timeout: (optional) Time to wait for positive procedure result.
        :param str technology: one of <LTE, TETRA, NR, ALL> - should be None when dist_name is specified.
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return: dict with full api response or requestMessage key
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-lock.html
        """
        if not (dist_name or technology):
            raise ValueError("dist_name or technology must be specified")

        if all([dist_name, technology]):
            raise ValueError("Only one of dist_name or technology must be specified")

        if technology not in ("LTE", "TETRA", "NR", "ALL", None):
            raise_value_error(param="technology",
                              value=str(technology),
                              subpage="tutorial-unlock.html")

        if dist_name and not isinstance(dist_name, list):
            dist_name = [dist_name]

        keys = ["distNames", "technology"]
        values = [dist_name, technology]
        parameters = {k: v for (k, v) in zip(keys, values) if v}

        response = self._api_client.execute_customer_procedure('unlock', parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def lock_cell_group(self, dist_name, timeout=60):
        """
        Locks iteratively all cells in the given NR cell group. This keyword sends two types of internal request operations:
        - get_bts_info: collects all data regarding cells and cell groups
        - lock_cell: cell lock for each cell in given cell group

        :param str dist_name: `NRCELLGRP_A` object to lock the cell group.
        :param Union[int,str] timeout: (optional) Timeout for each internal request operation, set to 60 by default.
        :raise NoCellsAvailable: If there are no NR cells commissioned or given cell group is empty
        :raise CellGroupDoesntExist: If there is no provided NR cell group on BTS
        :return string: It returns string with status.

        Example response

        ::
               "completed"

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-lock.html

        """
        cell_group_name = dist_name.split("/")[-1]
        bts_info = self.get_bts_info(timeout=timeout)
        nr_cells = bts_info['cells']['nr']
        self._raise_if_empty(nr_cells, "Currently there are no NR cells commissioned", NoCellsAvailable)
        cells_list = self._get_cells_for_cell_group(cell_group_name, bts_info)
        self._raise_if_empty(cells_list, "Currently there are no cells in given NR cell group", NoCellsAvailable)
        runtime_nr_cells = self._get_runtime_nr_cells(nr_cells, cells_list)
        cells_to_lock = list(runtime_nr_cells)
        self.lock(cells_to_lock, timeout)
        return "completed"

    @staticmethod
    def _get_cells_for_cell_group(cell_group_name, bts_info):
        group_exists = False
        cells_list = []
        for cell_group in bts_info['cellsGroup']:
            if cell_group['id']['internal'].split("/")[-1] == cell_group_name:
                cells_list.extend(cell_group['nrCellList'])
                group_exists = True
        if not group_exists:
            raise CellGroupDoesntExist('Provided cell group: {} does not exist on target host'.format(cell_group_name))
        return cells_list

    @staticmethod
    def _get_runtime_nr_cells(nr_cells, cells_list):
        runtime_nr_cells = []
        for nr_cell in nr_cells:
            if nr_cell['id']['configuration'].split("/")[-1] in cells_list:
                runtime_nr_cells.append(nr_cell['id']['internal'])
        return runtime_nr_cells

    @staticmethod
    def _raise_if_empty(test_object, msg, exception):
        if not test_object:
            raise exception(msg)

    def unlock_cell_group(self, dist_name, timeout=60):
        """
        Unlocks iteratively all cells in the given NR cell group. This keyword sends two types of internal request operations:
        - get_bts_info: collects all data regarding cells and cell groups
        - unlock_cell: cell unlock for each cell in given cell group

        :param str dist_name: `NRCELLGRP_A` object to unlock the cell group.
        :param Union[int,str] timeout: (optional) Timeout for each internal request operation, set to 60 by default.
        :raise NoCellsAvailable: If there are no NR cells commissioned or given cell group is empty
        :raise CellGroupDoesntExist: If there is no provided NR cell group on BTS
        :return string: It returns string with status.

        Example response

        ::

               "completed"

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-unlock.html

        """
        cell_group_name = dist_name.split("/")[-1]
        bts_info = self.get_bts_info(timeout=timeout)
        nr_cells = bts_info['cells']['nr']
        self._raise_if_empty(nr_cells, "Currently there are no NR cells commissioned", NoCellsAvailable)
        cells_list = self._get_cells_for_cell_group(cell_group_name, bts_info)
        self._raise_if_empty(cells_list, "Currently there are no cells in given NR cell group", NoCellsAvailable)
        runtime_nr_cells = self._get_runtime_nr_cells(nr_cells, cells_list)
        cells_to_unlock = list(runtime_nr_cells)
        self.unlock(cells_to_unlock, timeout)
        return "completed"

    def start_5g_uplink_ccm_test_prach(self, dist_name, interval,
                                       beam_pattern_id, receiving_slot,
                                       expectation_slot,
                                       preamble_index, accepted_timing_error,
                                       constant_offset,
                                       delay_pattern_single_step_duration,
                                       ru_mode, phys_cell_id,
                                       prach_configuration_index,
                                       pfa_target_prach_id,
                                       nrarfcn_ul=None, nrarfcn_dl=None,
                                       timeout=60, prach_root_sequence_index=None,
                                       zero_correlation_zone_config=None,
                                       prach_sequence_type=None, **kwargs):
        """
        Starts 5G `Prach` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1..3600] (step 0.1)
        :param List[int] beam_pattern_id: [0..1200].
        :param int receiving_slot: [0..1023].
        :param int expectation_slot: [0..1023].
        :param int preamble_index: [0..63].
        :param int accepted_timing_error: [0..999999].
        :param int constant_offset: [0..999999].
        :param int delay_pattern_single_step_duration: [0..1000].
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int prach_configuration_index: [0..255]
        :param str pfa_target_prach_id: Either 'P_None', 'P_01', 'P_001', 'P_0005', 'P_0001', 'P_005', 'P_05' or 'P_10'
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param int prach_root_sequence_index: [0..837].
        :param int zero_correlation_zone_config: [0..15].
        :param str prach_sequence_type: PRACH sequence type ["Unrestricted" | "RestrictedTypeA"]
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
              }
           }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        PERFORMANCE_TEST_TYPE = "Prach"

        prach_schema = CCMUplinkPrach(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, performance_test_type=PERFORMANCE_TEST_TYPE,
                                      receiving_slot=receiving_slot, expectation_slot=expectation_slot,
                                      preamble_index=preamble_index, accepted_timing_error=accepted_timing_error,
                                      constant_offset=constant_offset,
                                      delay_pattern_single_step_duration=delay_pattern_single_step_duration,
                                      ru_mode=ru_mode, phys_cell_id=phys_cell_id, nrarfcn_dl=nrarfcn_dl,
                                      prach_configuration_index=prach_configuration_index,
                                      pfa_target_prach_id=pfa_target_prach_id,
                                      prach_root_sequence_index=prach_root_sequence_index,
                                      zero_correlation_zone_config=zero_correlation_zone_config,
                                      prach_sequence_type=prach_sequence_type)

        parameters = prach_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

